def _env_truthy(name: str) -> bool:
    return os.environ.get(name, "").strip().lower() in {"1", "true", "yes", "on"}


def _int_env(
    name: str,
    default: int,
    *,
    min_value: int = 0,
    max_value: int = ACCOUNT_MARKET_INVENTORY_MAX_RECORD_LIMIT,
) -> int:
    try:
        value = int(os.environ.get(name, "").strip() or default)
    except (TypeError, ValueError):
        return default
    return max(min_value, min(max_value, value))


def _inventory_get(source: Any, *names: str, default: Any = None) -> Any:
    if source is None:
        return default
    if isinstance(source, Mapping):
        for name in names:
            if name in source:
                return source[name]
        return default
    for name in names:
        if hasattr(source, name):
            return getattr(source, name)
    return default


def _inventory_text(value: Any, fallback: str = "") -> str:
    if value is None:
        return fallback
    if isinstance(value, Mapping):
        nested = _inventory_get(value, "value", "amount", "balance")
        if nested is not None and nested is not value:
            return _inventory_text(nested, fallback=fallback)
    text = str(value)
    return text if text else fallback


def _inventory_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    if isinstance(value, (int, float, Decimal)):
        return value != 0
    return str(value).strip().lower() in {"1", "true", "yes", "on"}


def _inventory_decimal(value: Any) -> Decimal:
    text = _inventory_text(value, fallback="0").replace(",", "")
    try:
        return Decimal(text)
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _inventory_decimal_text(value: Any) -> str:
    return _inventory_format_decimal(_inventory_decimal(value))


def _inventory_format_decimal(value: Decimal) -> str:
    text = format(value.normalize(), "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text or "0"


def _inventory_balance_text(source: Any, *names: str) -> str:
    for name in names:
        value = _inventory_get(source, name)
        if value is not None:
            return _inventory_decimal_text(value)
    return "0"


def _inventory_product_id(product: Any) -> str:
    return _inventory_text(_inventory_get(product, "product_id")).upper()


def _inventory_base_currency(product: Any) -> str:
    base = _inventory_text(
        _inventory_get(product, "base_currency_id", "base_currency")
    ).upper()
    if base:
        return base
    product_id = _inventory_product_id(product)
    return product_id.rsplit("-", 1)[0] if "-" in product_id else ""


def _inventory_quote_currency(product: Any) -> str:
    quote = _inventory_text(
        _inventory_get(product, "quote_currency_id", "quote_currency")
    ).upper()
    if quote:
        return quote
    product_id = _inventory_product_id(product)
    return product_id.rsplit("-", 1)[1] if "-" in product_id else ""


def _bounded_inventory_rows(
    rows: list[dict[str, Any]],
    limit: int,
) -> tuple[list[dict[str, Any]], bool, int]:
    if limit <= 0:
        return [], bool(rows), len(rows)
    return rows[:limit], len(rows) > limit, len(rows)


def _account_market_inventory_provider_limit(
    payload: Mapping[str, Any],
    key: str,
    env_name: str,
    default: int,
) -> int:
    limits = _inventory_get(payload, "limits", default={})
    raw_value = _inventory_get(payload, key)
    if raw_value is None:
        raw_value = _inventory_get(limits, key)
    if raw_value is not None:
        try:
            return max(
                0,
                min(ACCOUNT_MARKET_INVENTORY_MAX_RECORD_LIMIT, int(raw_value)),
            )
        except (TypeError, ValueError):
            pass
    return _int_env(env_name, default)


def _account_market_inventory_disabled_payload() -> dict[str, Any]:
    disabled_reason = (
        f"Coinbase account/market inventory reads are disabled; set "
        f"{ACCOUNT_MARKET_INVENTORY_READS_ENV}=true to enable read-only "
        "backend Coinbase product, wallet, and fill reads."
    )
    return {
        "enabled": False,
        "data_source": "disabled",
        "limits": {
            "product_limit": _int_env(
                ACCOUNT_MARKET_INVENTORY_PRODUCT_LIMIT_ENV,
                ACCOUNT_MARKET_INVENTORY_DEFAULT_PRODUCT_LIMIT,
            ),
            "wallet_limit": _int_env(
                ACCOUNT_MARKET_INVENTORY_WALLET_LIMIT_ENV,
                ACCOUNT_MARKET_INVENTORY_DEFAULT_WALLET_LIMIT,
            ),
            "fill_limit": _int_env(
                ACCOUNT_MARKET_INVENTORY_FILL_LIMIT_ENV,
                ACCOUNT_MARKET_INVENTORY_DEFAULT_FILL_LIMIT,
            ),
        },
        "products": [],
        "wallets": {},
        "fills": [],
        "errors": {
            "product_catalog": disabled_reason,
            "spot_wallets": disabled_reason,
            "spot_balances": disabled_reason,
            "spot_fills": disabled_reason,
        },
        "read_only_coinbase_requests": [],
        "live_coinbase_read_ran": False,
    }


def _account_market_inventory_default_provider() -> Mapping[str, Any]:
    """Fetch read-only Coinbase inventory inputs when explicitly enabled."""

    if not _env_truthy(ACCOUNT_MARKET_INVENTORY_READS_ENV):
        return _account_market_inventory_disabled_payload()

    product_limit = _int_env(
        ACCOUNT_MARKET_INVENTORY_PRODUCT_LIMIT_ENV,
        ACCOUNT_MARKET_INVENTORY_DEFAULT_PRODUCT_LIMIT,
    )
    wallet_limit = _int_env(
        ACCOUNT_MARKET_INVENTORY_WALLET_LIMIT_ENV,
        ACCOUNT_MARKET_INVENTORY_DEFAULT_WALLET_LIMIT,
    )
    fill_limit = _int_env(
        ACCOUNT_MARKET_INVENTORY_FILL_LIMIT_ENV,
        ACCOUNT_MARKET_INVENTORY_DEFAULT_FILL_LIMIT,
    )
    payload: dict[str, Any] = {
        "enabled": True,
        "data_source": "coinbase_read_only_rest",
        "limits": {
            "product_limit": product_limit,
            "wallet_limit": wallet_limit,
            "fill_limit": fill_limit,
        },
        "products": [],
        "wallets": {},
        "fills": [],
        "errors": {},
        "read_only_coinbase_requests": [],
        "live_coinbase_read_ran": False,
    }

    try:
        from external.coinbase_client import list_public_product_dicts

        payload["read_only_coinbase_requests"].append("get_public_products")
        payload["live_coinbase_read_ran"] = True
        payload["products"] = list_public_product_dicts(product_type=ProductType.SPOT.value)
    except Exception as exc:  # pragma: no cover - exercised through injected providers.
        payload["errors"]["product_catalog"] = str(exc)
        payload["errors"]["spot_balances"] = str(exc)

    try:
        from core.action_condition_guard import rest_credentials_configured

        if rest_credentials_configured():
            import configuration

            payload["read_only_coinbase_requests"].append("get_accounts")
            payload["live_coinbase_read_ran"] = True
            payload["wallets"] = configuration.rest_get_account_wallets()
            payload["read_only_coinbase_requests"].append("list_fills")
            fills_response = configuration.get_rest_client().list_fills(
                limit=fill_limit
            )
            if isinstance(fills_response, Mapping):
                payload["fills"] = list(fills_response.get("fills") or [])
            else:
                payload["fills"] = list(fills_response or [])
        else:
            reason = "Coinbase REST credentials are not configured."
            payload["errors"]["spot_wallets"] = reason
            payload["errors"]["spot_balances"] = reason
            payload["errors"]["spot_fills"] = reason
    except Exception as exc:  # pragma: no cover - exercised through injected providers.
        reason = str(exc)
        payload["errors"]["spot_wallets"] = reason
        payload["errors"]["spot_balances"] = reason
        payload["errors"]["spot_fills"] = reason

    return payload


def _string_or_none(value: Any) -> str | None:
    if value is None:
        return None
    return str(value)


def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _stable_read_id(prefix: str, *parts: str) -> str:
    material = "|".join([prefix, *parts])
    return f"{prefix}:{uuid.uuid5(uuid.NAMESPACE_URL, material)}"


def _csrf_required() -> bool:
    return os.environ.get(
        "COINBASE_ADMIN_API_CSRF_REQUIRED",
        "",
    ).strip().lower() in {"1", "true", "yes"}


def _surface_method_and_path(surface: str) -> tuple[str, str]:
    first, _, rest = surface.partition(" ")
    if rest.startswith("/"):
        return first, rest
    if "WebSocket" in surface:
        return "WEBSOCKET", surface
    return "UNKNOWN", surface


def _spot_sweep_scheduler_binding_evidence(
    *,
    scheduler_statuses: list[dict[str, Any]],
    latest_control_state: Mapping[str, Any],
    operation_lock_status: Mapping[str, Any],
) -> dict[str, Any]:
    paused_sweep_config_id = ""
    if (
        latest_control_state.get("control_state_after")
        == SpotSweepAutomationControlState.PAUSED.value
    ):
        paused_sweep_config_id = str(latest_control_state.get("sweep_config_id") or "")
    operation_lock_busy = bool(
        operation_lock_status.get("exists")
        and not operation_lock_status.get("stale")
    )
    bound_statuses: list[dict[str, Any]] = []
    run_limit_statuses: list[dict[str, Any]] = []
    counts = {
        "due": 0,
        "not_due": 0,
        "disabled": 0,
        "max_runs_reached": 0,
        "blocked_by_control": 0,
        "blocked_by_lock": 0,
        "dispatchable": 0,
    }

    for status in scheduler_statuses:
        item = dict(status)
        decision = item.get("scheduler_decision") or {}
        if not isinstance(decision, Mapping):
            decision = {}
        decision_value = str(decision.get("decision") or "")
        sweep_config_id = str(item.get("sweep_config_id") or "")
        control_state = (
            SpotSweepAutomationControlState.PAUSED.value
            if sweep_config_id and sweep_config_id == paused_sweep_config_id
            else SpotSweepAutomationControlState.ACTIVE.value
        )
        is_due = decision_value == SpotPortfolioSweepAutomationDecision.DUE.value
        is_not_due = decision_value == SpotPortfolioSweepAutomationDecision.NOT_DUE.value
        is_disabled = decision_value == SpotPortfolioSweepAutomationDecision.DISABLED.value
        is_run_limited = (
            decision_value
            == SpotPortfolioSweepAutomationDecision.MAX_RUNS_REACHED.value
        )
        if is_due:
            counts["due"] += 1
        if is_not_due:
            counts["not_due"] += 1
        if is_disabled:
            counts["disabled"] += 1
        if is_run_limited:
            counts["max_runs_reached"] += 1

        dispatch_blockers: list[SpotSweepAutomationExecutionBlocker] = []
        binding_status = SpotSweepAutomationSchedulerBindingStatus.UNKNOWN
        if control_state == SpotSweepAutomationControlState.PAUSED.value:
            binding_status = (
                SpotSweepAutomationSchedulerBindingStatus.BLOCKED_BY_PAUSE_CONTROL
            )
            dispatch_blockers.append(
                SpotSweepAutomationExecutionBlocker.SCHEDULER_DISPATCH_PAUSED
            )
            counts["blocked_by_control"] += 1
        elif is_run_limited:
            binding_status = SpotSweepAutomationSchedulerBindingStatus.MAX_RUNS_REACHED
            dispatch_blockers.append(
                SpotSweepAutomationExecutionBlocker.SCHEDULER_DISPATCH_MAX_RUNS_REACHED
            )
        elif is_disabled:
            binding_status = SpotSweepAutomationSchedulerBindingStatus.DISABLED
            dispatch_blockers.append(
                SpotSweepAutomationExecutionBlocker.SCHEDULER_DISPATCH_DISABLED
            )
        elif is_not_due:
            binding_status = SpotSweepAutomationSchedulerBindingStatus.NOT_DUE
            dispatch_blockers.append(
                SpotSweepAutomationExecutionBlocker.SCHEDULER_DISPATCH_NOT_DUE
            )
        elif is_due and operation_lock_busy:
            binding_status = (
                SpotSweepAutomationSchedulerBindingStatus.BLOCKED_BY_OPERATION_LOCK
            )
            dispatch_blockers.append(
                SpotSweepAutomationExecutionBlocker.SCHEDULER_DISPATCH_OPERATION_LOCK_BUSY
            )
            counts["blocked_by_lock"] += 1
        elif is_due:
            binding_status = (
                SpotSweepAutomationSchedulerBindingStatus.DUE_DISPATCH_LIVE_DISABLED
            )
            dispatch_blockers.append(
                SpotSweepAutomationExecutionBlocker.SCHEDULER_DISPATCH_LIVE_DISABLED
            )
            counts["dispatchable"] += 1

        attempt_count = int(decision.get("attempt_count") or 0)
        max_runs = int(decision.get("max_runs") or 0)
        remaining_runs = max(max_runs - attempt_count, 0) if max_runs else 0
        item.update(
            {
                "scheduler_binding_status": binding_status.value,
                "scheduler_dispatchable": False,
                "would_dispatch_if_service_modeled": False,
                "would_dispatch_if_live_enabled": (
                    binding_status
                    == SpotSweepAutomationSchedulerBindingStatus.DUE_DISPATCH_LIVE_DISABLED
                ),
                "dispatch_blockers": [blocker.value for blocker in dispatch_blockers],
                "control_state_after": control_state,
                "run_limit_reached": is_run_limited,
                "run_limit_remaining": remaining_runs,
                "scheduler_dispatch_contract_status": (
                    AdminApiModuleSupportStatus.COMMAND_DRAFT_LIVE_DISABLED.value
                ),
                "scheduler_decision_contract_status": (
                    AdminApiModuleSupportStatus.READ_ONLY_READY.value
                ),
                "browser_scheduler_authority": False,
                "bff_authority": "forward_only_no_execution",
            }
        )
        bound_statuses.append(item)
        run_limit_statuses.append(
            {
                "campaign_id": item.get("campaign_id"),
                "sweep_config_id": sweep_config_id,
                "decision": decision_value
                or SpotSweepAutomationSchedulerBindingStatus.UNKNOWN.value,
                "attempt_count": attempt_count,
                "max_runs": max_runs,
                "remaining_runs": remaining_runs,
                "run_limit_reached": is_run_limited,
                "run_limit_contract_status": (
                    AdminApiModuleSupportStatus.READ_ONLY_READY.value
                ),
                "backend_owned": True,
                "read_only": True,
                "scheduler_invoked": False,
                "sweep_runner_invoked": False,
                "coinbase_orders_submitted": False,
                "live_coinbase_orders_ran": False,
            }
        )

    return {
        "scheduler_statuses": bound_statuses,
        "run_limit_statuses": run_limit_statuses,
        "summary": {
            "scheduler_status_count": len(bound_statuses),
            "scheduler_due_count": counts["due"],
            "scheduler_not_due_count": counts["not_due"],
            "scheduler_disabled_count": counts["disabled"],
            "scheduler_max_runs_reached_count": counts["max_runs_reached"],
            "scheduler_due_blocked_by_control_count": counts["blocked_by_control"],
            "scheduler_due_blocked_by_lock_count": counts["blocked_by_lock"],
            "scheduler_dispatchable_count": counts["dispatchable"],
            "scheduler_decision_contract_status": (
                AdminApiModuleSupportStatus.READ_ONLY_READY.value
            ),
            "scheduler_dispatch_contract_status": (
                AdminApiModuleSupportStatus.COMMAND_DRAFT_LIVE_DISABLED.value
            ),
            "run_limit_contract_status": (
                AdminApiModuleSupportStatus.READ_ONLY_READY.value
            ),
            "backend_owned": True,
            "read_only": True,
            "scheduler_invoked": False,
            "sweep_runner_invoked": False,
            "coinbase_orders_submitted": False,
            "live_coinbase_orders_ran": False,
        },
    }


def _plural(count: int, singular: str, plural: str | None = None) -> str:
    return singular if count == 1 else (plural or f"{singular}s")


def _spot_sweep_service_postures(
    *,
    campaign_count: int,
    sweep_config_count: int,
    retry_plan_count: int,
    retry_ready_count: int,
    scheduler_decision_summary: Mapping[str, Any],
    latest_control_state: Mapping[str, Any],
    current_read_evidence_routes: list[str],
    command_routes: list[str],
    missing_contracts: list[str],
) -> list[SpotSweepAutomationServicePostureItem]:
    blocked_by_control = int(
        scheduler_decision_summary.get("scheduler_due_blocked_by_control_count") or 0
    )
    latest_control_value = str(
        latest_control_state.get("control_state_after")
        or latest_control_state.get("control_state")
        or SpotSweepAutomationControlState.ACTIVE.value
    )
    paused = (
        latest_control_value == SpotSweepAutomationControlState.PAUSED.value
        or blocked_by_control > 0
    )
    configured_gate = (
        AdminApiGateStatus.PASSED
        if campaign_count > 0 or sweep_config_count > 0
        else AdminApiGateStatus.WARNING
    )
    retry_gate = (
        AdminApiGateStatus.WARNING
        if retry_ready_count > 0
        else (
            AdminApiGateStatus.PASSED
            if retry_plan_count > 0
            else AdminApiGateStatus.NOT_APPLICABLE
        )
    )
    not_modeled_gate = (
        AdminApiGateStatus.BLOCKED
        if missing_contracts
        else AdminApiGateStatus.PASSED
    )
    configured_evidence = (
        f"{campaign_count} {_plural(campaign_count, 'campaign')}; "
        f"{sweep_config_count} {_plural(sweep_config_count, 'sweep config')}"
    )
    paused_evidence = (
        f"{SpotSweepAutomationControlState.PAUSED.value if paused else SpotSweepAutomationControlState.ACTIVE.value}; "
        f"{blocked_by_control} due {_plural(blocked_by_control, 'row')} "
        "blocked by pause control"
    )
    retry_evidence = (
        f"{retry_ready_count} ready / "
        f"{retry_plan_count} {_plural(retry_plan_count, 'plan')}"
    )
    missing_evidence = (
        f"{len(missing_contracts)} missing "
        f"{_plural(len(missing_contracts), 'contract')}"
    )
    local_control_routes = [
        route
        for route in command_routes
        if route == "POST /api/v1/spot/sweep/automation-controls"
    ]
    automation_run_routes = [
        route
        for route in command_routes
        if route == "POST /api/v1/spot/sweep/automation-runs"
    ]

    return [
        SpotSweepAutomationServicePostureItem(
            posture=SpotSweepAutomationServicePosture.CONFIGURED,
            label="Configured",
            support_status=AdminApiModuleSupportStatus.READ_ONLY_READY,
            gate_status=configured_gate,
            current_evidence=configured_evidence,
            read_routes=current_read_evidence_routes,
            backend_contracts=[
                "business/spot_campaign.py",
                "business/spot_portfolio_sweep.py",
            ],
            detail=(
                "Campaign and sweep configuration posture is read from "
                "backend-owned campaign snapshots and sweep ledgers."
            ),
        ),
        SpotSweepAutomationServicePostureItem(
            posture=SpotSweepAutomationServicePosture.PAUSED,
            label="Paused",
            support_status=AdminApiModuleSupportStatus.COMMAND_DRAFT_LIVE_DISABLED,
            gate_status=AdminApiGateStatus.WARNING if paused else AdminApiGateStatus.PASSED,
            current_evidence=paused_evidence,
            read_routes=["GET /api/v1/spot/sweep/automation-service"],
            command_routes=local_control_routes,
            unsupported_behaviors=[
                "scheduler execution",
                "sweep runner execution",
                "Coinbase order submission",
            ],
            backend_contracts=[
                "application/admin_api/spot_sweep_automation_control.py",
                "application/admin_api/command_service.py::record_spot_sweep_automation_control",
            ],
            operator_action_available=True,
            detail=(
                "Pause/resume posture is backend local control evidence only; "
                "it does not invoke a scheduler, runner, or Coinbase order."
            ),
        ),
        SpotSweepAutomationServicePostureItem(
            posture=SpotSweepAutomationServicePosture.RETRYABLE,
            label="Retryable",
            support_status=AdminApiModuleSupportStatus.COMMAND_DRAFT_LIVE_DISABLED,
            gate_status=retry_gate,
            current_evidence=retry_evidence,
            read_routes=["GET /api/v1/spot/sweep/automation-service"],
            command_routes=local_control_routes,
            unsupported_behaviors=[
                "retry executor",
                "sweep runner execution",
                "Coinbase order submission",
            ],
            backend_contracts=[
                "business/spot_campaign.py::build_spot_campaign_retry_plan",
                "application/admin_api/command_service.py::record_spot_sweep_automation_control",
            ],
            operator_action_available=retry_ready_count > 0,
            detail=(
                "Retryable posture is review and local retry-intent evidence; "
                "retry execution remains behind backend-owned execution gates."
            ),
        ),
        SpotSweepAutomationServicePostureItem(
            posture=SpotSweepAutomationServicePosture.UNSUPPORTED,
            label="Unsupported",
            support_status=AdminApiModuleSupportStatus.UNSUPPORTED,
            gate_status=AdminApiGateStatus.BLOCKED,
            current_evidence="browser display_only; BFF forward_only_no_execution",
            unsupported_behaviors=[
                "browser scheduler authority",
                "BFF runner authority",
                "direct Coinbase calls",
                "route-local FastAPI execution",
                "second automation path",
            ],
            backend_contracts=[
                "AGENTS.md",
                "docs/plans/ADMIN_RELEASE_0_1_ROUTE_TO_UI_MATRIX.md",
            ],
            detail=(
                "Unsupported automation behavior must remain explicit and must "
                "not be filled by browser code, BFF services, route-local "
                "executors, or a second trading path."
            ),
        ),
        SpotSweepAutomationServicePostureItem(
            posture=SpotSweepAutomationServicePosture.NOT_MODELED,
            label="Not modeled",
            support_status=AdminApiModuleSupportStatus.NOT_MODELED,
            gate_status=not_modeled_gate,
            current_evidence=missing_evidence,
            read_routes=["GET /api/v1/spot/sweep/automation-service"],
            command_routes=automation_run_routes,
            missing_contracts=missing_contracts,
            backend_contracts=missing_contracts,
            detail=(
                "Unmodeled execution contracts are backend blockers. Operators "
                "can inspect them here, but the frontend must not implement "
                "scheduler, retry, reconciliation, or live Coinbase authority."
            ),
        ),
    ]


def _route_availability(surface: str, action_class: AdminApiActionClass) -> AdminApiRouteAvailability:
    if "WebSocket" in surface:
        return AdminApiRouteAvailability.CONTRACT_PENDING
    if surface.startswith("POST /api/v1") and action_class in {
        AdminApiActionClass.LIVE_EXCHANGE_PLACE,
        AdminApiActionClass.LIVE_EXCHANGE_CANCEL,
    }:
        return AdminApiRouteAvailability.LIVE_DISABLED
    return AdminApiRouteAvailability.AVAILABLE


def _frontend_safe(surface: str, action_class: AdminApiActionClass) -> bool:
    if "WebSocket" in surface:
        return False
    return action_class == AdminApiActionClass.READ_ONLY or surface.startswith("POST /api/v1")


