        def semantic_guard(
            semantic_guard_id: AdminFuturesCommandSemanticGuard,
            *,
            applies_to_fields: list[AdminFuturesCommandRequestField],
            evidence_routes: list[AdminFuturesCommandEvidenceRoute] | None = None,
            required_evidence_refs: list[str] | None = None,
            missing_evidence_refs: list[str] | None = None,
            identity_semantic: bool = False,
            risk_semantic: bool = False,
            audit_semantic: bool = False,
            execution_semantic: bool = False,
            detail: str,
        ) -> AdminFuturesCommandSemanticGuardItem:
            route_refs = (
                guard_evidence_route_defaults[semantic_guard_id]
                if evidence_routes is None
                else evidence_routes
            )
            required_refs = (
                guard_required_evidence_refs[semantic_guard_id]
                if required_evidence_refs is None
                else required_evidence_refs
            )
            missing_refs = (
                list(required_refs)
                if missing_evidence_refs is None
                else missing_evidence_refs
            )
            return AdminFuturesCommandSemanticGuardItem(
                semantic_guard=semantic_guard_id,
                applies_to_fields=applies_to_fields,
                evidence_routes=route_refs,
                evidence_route_count=len(route_refs),
                required_evidence_refs=required_refs,
                required_evidence_count=len(required_refs),
                missing_evidence_refs=missing_refs,
                missing_evidence_count=len(missing_refs),
                identity_semantic=identity_semantic,
                risk_semantic=risk_semantic,
                audit_semantic=audit_semantic,
                execution_semantic=execution_semantic,
                detail=detail,
            )

        def prerequisite(
            prerequisite_id: AdminFuturesCommandPrerequisite,
            *,
            status: AdminApiGateStatus = AdminApiGateStatus.BLOCKED,
            source: AdminFuturesEvidenceSource = AdminFuturesEvidenceSource.BACKEND_CONTRACT,
            evidence_route: str | None = None,
            resolved: bool = False,
            detail: str,
        ) -> AdminFuturesCommandPrerequisiteItem:
            return AdminFuturesCommandPrerequisiteItem(
                prerequisite=prerequisite_id,
                status=status,
                source=source,
                evidence_route=evidence_route,
                resolved=resolved,
                blocking=status != AdminApiGateStatus.PASSED,
                detail=detail,
            )

        def observed_account_prerequisite(
            prerequisite_id: AdminFuturesCommandPrerequisite,
            evidence: AdminFuturesEvidenceItem,
        ) -> AdminFuturesCommandPrerequisiteItem:
            observed = evidence.status == AdminFuturesEvidenceStatus.OBSERVED
            return prerequisite(
                prerequisite_id,
                status=(
                    AdminApiGateStatus.PASSED
                    if observed
                    else AdminApiGateStatus.BLOCKED
                ),
                source=evidence.source,
                evidence_route="/api/v1/futures/account",
                resolved=observed,
                detail=evidence.detail or f"{prerequisite_id.value} evidence unavailable.",
            )

        def position_scope_prerequisite(
            *,
            require_open_position: bool,
        ) -> AdminFuturesCommandPrerequisiteItem:
            resolved = observed_position_scope if require_open_position else observed_product_scope
            return prerequisite(
                AdminFuturesCommandPrerequisite.POSITION_SCOPE,
                status=(
                    AdminApiGateStatus.PASSED
                    if resolved
                    else AdminApiGateStatus.BLOCKED
                ),
                source=(
                    AdminFuturesEvidenceSource.RUNTIME_POSITIONS
                    if require_open_position
                    else AdminFuturesEvidenceSource.PRODUCTS_JSON
                ),
                evidence_route="/api/v1/futures/positions",
                resolved=resolved,
                detail=(
                    "Open position scope is required for futures close/reduce and "
                    "reconciliation commands."
                    if require_open_position
                    else "Configured or observed futures product scope is required before placement contracts can exist."
                ),
            )

